"""Tests for the plain-English sentence generated by momp.onset.describe."""
import pytest

from momp.onset import definition as dfn
from momp.onset.describe import describe

BASE = """\
id: t
version: 1
title: T
citation: TODO
wording: TODO
status: draft
notes: n
wet_day: at least 1 mm
"""


@pytest.mark.parametrize("ident, phrases", [
    ("icpac", ["Onset is the first day from 1 May to 30 September that is a wet day (at least 1 mm), "
               "on which the 3-day total is more than 20 mm, and that is not followed by a dry run of "
               "at least 7 days within the next 21 days."]),
    ("moron_robertson", ["from 1 April to 31 October", "wet day (at least 1 mm)", "5-day total is at least "
                         "wet_spell_amount (the mean 5-day total from 1 May to 30 September)",
                         "dry window of 10 days totalling less than 5 mm",
                         "within the 30 days after the 5-day window"]),
    ("moron_robertson_mok", ["from 2 June to 31 October", "wet_spell_amount"]),
    ("sivakumar", ["from 1 May to 31 October", "3-day total is at least 20 mm", "dry run of more than 7 days",
                   "a dry day has less than 1 mm", "within the next 30 days"]),
    ("marteau", ["begins 2 consecutive wet days (at least 1 mm)", "2-day total is more than 20 mm",
                 "dry window of 7 days totalling less than 5 mm", "within the 20 days after the 2-day window"]),
    ("omotosho", ["from 1 March to 31 July", "10-day total is at least 20 mm",
                  "total over days 11 to 20 (counting that day as day 1) is at least 20 mm"]),
    ("liebmann_marengo", ["day after the minimum of the cumulative rainfall anomaly",
                          "the mean daily rain over the whole year (mean_daily_rain)",
                          "from 1 January to 31 December"]),
    ("dunning", ["day after the minimum", "harmonic analysis", "50 days before the climatological onset",
                 "the climatological cessation"]),
])
def test_registry_sentences(ident, phrases):
    """Each registry entry's sentence contains its key phrases."""
    text = describe(dfn.load(ident))
    for phrase in phrases:
        assert phrase in text, text
    assert text.endswith(".")


def test_starting_within_and_season_to_date_and_counts():
    """Constructs the registry does not use: starts-within spells, season to date, wet-day counts, first wet day."""
    text = describe(dfn.loads(BASE + """\
season: {from: 11-01, to: 03-31}
onset:
  window: 4 days
  require:
    - wet days: at least 3
    - total: at least 51 mm
      over: season to date
  reject if:
    - dry window: 10 days with less than 5 mm
      starting within: 30 days after window
  report: first wet day
"""))
    assert "from 1 November to 31 March of the following year" in text
    assert "has at least 3 wet days (at least 1 mm) over days 1 to 4" in text
    assert "total rain from the start of the search window to that day is at least 51 mm" in text
    assert "that starts within the 30 days after the 4-day window" in text
    assert "first wet day within days 1 to 4" in text


def test_named_seasons_quantile_and_generic_span():
    """Named seasons, quantile thresholds, bare offset spans and cessation offsets."""
    text = describe(dfn.loads(BASE + """\
seasons:
  long_rains: {from: 02-01, to: 05-31}
  short_rains: {from: 09-01, to: 12-31}
thresholds:
  heavy: {quantile of totals over: 3 days, quantile: 0.8, during: 06-01 to 09-30}
onset:
  window: 3 days
  require:
    - total: more than heavy
    - all days: wet
      over: days 2 to 3
  reject if:
    - dry run: at least 5 days
      within: days 10 to 20
"""))
    assert "in each of the seasons long_rains (from 1 February to 31 May) and short_rains" in text
    assert "0.8 quantile of 3-day totals from 1 June to 30 September" in text
    assert "every day over days 2 to 3 is wet" in text
    assert "within days 10 to 20 (counting the onset day as day 1)" in text


def test_derived_with_positive_offset():
    """A derived season bound with a positive offset reads 'after'."""
    text = describe(dfn.loads(BASE + """\
seasons: {derive: harmonic regime, from: climatological onset - 1 day, to: climatological cessation + 10 days}
thresholds:
  m: {mean daily rain: true}
curve: {accumulate: rain minus m, onset: day of minimum}
"""))
    assert "1 day before the climatological onset" in text
    assert "10 days after the climatological cessation" in text
    assert "Onset is the day of the minimum" in text
